<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api,post,date} from '../api';import BlockEditor from '../components/BlockEditor.vue';import WorkoutChart from '../components/WorkoutChart.vue'
const props=defineProps<{athlete:any}>();const models=ref<any[]>([]),saved=ref<any[]>([]),modelId=ref(''),name=ref('Nuovo allenamento'),blocks=ref<any[]>([{duration_s:600,target:{kind:'constant',watts:150}}]),paths=ref(1000),seed=ref(42),error=ref(''),busy=ref(false),prediction=ref<any>(null),scenarioIndex=ref(0),importText=ref(''),importFormat=ref('json'),showImport=ref(false)
const scenario=computed(()=>prediction.value?.scenarios[scenarioIndex.value])
const plotted=computed(()=>scenario.value?{elapsed:scenario.value.target.map((_:any,i:number)=>i),target:scenario.value.target,power_mean:scenario.value.power.mean,power_low:scenario.value.power.lower,power_high:scenario.value.power.upper,hr_chain:scenario.value.hr.mean,hr_low:scenario.value.hr.lower,hr_high:scenario.value.hr.upper}:null)
const duration=computed(()=>{const total=(bs:any[]):number=>bs.reduce((a,b)=>a+(b.repeat?b.repeat*total(b.blocks):Number(b.duration_s)||0),0);return total(blocks.value)})
function choices(){const c:any={};function walk(bs:any[],prefix=''){bs.forEach((b,i)=>{const k=prefix+i;if(b.repeat)walk(b.blocks,k+'.');else if(b.target.kind==='range'){c[k]={mode:b.choice_mode||''};if(b.choice_mode==='profile')c[k].points=JSON.parse(b.choice_json||'[]');if(b.choice_mode==='scenarios')c[k].values=JSON.parse(b.choice_json||'{}')}})}walk(blocks.value);return c}
async function load(){models.value=await api(`/athletes/${props.athlete.id}/models`);saved.value=await api(`/athletes/${props.athlete.id}/predictions`)}
function importDraft(){try{let d:any;if(importFormat.value==='json')d=JSON.parse(importText.value);else{const rows=importText.value.trim().split(/\r?\n/);if(rows.shift()!=='duration_s,target_w')throw new Error('Header CSV: duration_s,target_w');d={schema_version:1,name:'Import CSV',blocks:rows.map(r=>{const [n,p]=r.split(',').map(Number);return {duration_s:n,target:{kind:'constant',watts:p}}})}}if(d.schema_version!==1||!Array.isArray(d.blocks))throw new Error('JSON v1 con blocks richiesto');blocks.value=d.blocks;name.value=d.name||'Import';showImport.value=false;error.value=''}catch(e:any){error.value=e.message}}
async function readFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){importFormat.value=f.name.endsWith('.csv')?'csv':'json';importText.value=await f.text();showImport.value=true}}
async function simulate(){busy.value=true;error.value='';try{const c=choices();const p=await post(`/athletes/${props.athlete.id}/prescriptions`,{draft:{schema_version:1,name:name.value,blocks:blocks.value},choices:c});prediction.value=await post(`/prescriptions/${p.id}/predictions`,{model_id:modelId.value,choices:c,paths:paths.value,seed:seed.value});scenarioIndex.value=0;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function open(id:string){try{prediction.value=await api('/predictions/'+id);scenarioIndex.value=0}catch(e:any){error.value=e.message}}
onMounted(async()=>{try{await load()}catch(e:any){error.value=e.message}})
</script>
<template><div class="page-heading"><div><p class="eyebrow">PRIMA DELL’ESECUZIONE</p><h1>Prepara un allenamento</h1><p>Una prescrizione esplicita. Una previsione salvata prima di partire.</p></div><label class="button secondary">Importa prescrizione<input type="file" accept=".json,.csv" @change="readFile" hidden></label></div><div class="error" v-if="error">{{error}}</div><details class="card"><summary>Formato di importazione riconosciuto</summary><p>CSV: header <code>duration_s,target_w</code>, una riga per blocco, ripetizioni espanse. JSON v1: blocchi e ripetizioni con potenze in W e durate intere in secondi. I range richiedono una scelta esplicita dopo l’import.</p><div class="actions"><a href="/api/examples/prescription.csv">Esempio CSV ↓</a><a href="/api/examples/prescription.json">Esempio JSON ↓</a><a href="/api/examples/prescription-range.json">Esempio con range ↓</a><button class="text-button" @click="showImport=!showImport">Incolla contenuto</button></div></details><section class="card" v-if="showImport"><select v-model="importFormat"><option value="json">JSON</option><option value="csv">CSV</option></select><textarea rows="8" v-model="importText"></textarea><button @click="importDraft">Carica nell’editor</button></section><section class="card"><div class="section-heading"><label>Nome allenamento<input v-model="name"></label><span class="pill">{{Math.floor(duration/60)}} min {{duration%60}} s</span></div><BlockEditor :blocks="blocks"/><p class="caption">Un range non rappresenta una distribuzione della potenza eseguita. Nessuna HR osservata viene usata per inizializzare questa previsione.</p><div class="form-grid"><label>Versione modello<select v-model="modelId"><option value="">Scegli una versione…</option><option v-for="m in models" :value="m.id">{{date(m.created_at)}} · {{m.id.slice(0,8)}}</option></select></label><label>Traiettorie Monte Carlo<input type="number" min="1" max="1000" v-model.number="paths"></label><label>Seed<input type="number" min="0" step="1" v-model.number="seed"></label></div><p class="notice" v-if="!models.length">Nessun modello disponibile. La prima identificazione va avviata nella sezione Identificazione.</p><button @click="simulate" :disabled="busy||!modelId">{{busy?'Simulazione in corso…':'Simula e salva previsione'}}</button></section><template v-if="prediction"><div class="notice">Previsione salvata il {{date(prediction.created_at)}} · {{prediction.id.slice(0,8)}}. Prescrizione e modello di questo snapshot non verranno modificati.</div><p class="warning" v-for="w in prediction.warnings">{{w}}</p><label>Scenario<select v-model="scenarioIndex"><option v-for="(s,i) in prediction.scenarios" :value="i">{{s.name}}</option></select></label><WorkoutChart v-if="plotted" :series="plotted" bands title="Prescrizione → potenza → HR"/></template><section class="card" v-if="saved.length"><h2>Previsioni salvate</h2><button v-for="p in saved" class="secondary" @click="open(p.id)">{{p.prescription_original.name}} · {{date(p.created_at)}}</button></section></template>
